("Orphan" = zero in-links from any other crawled sitemap page; "unreachable" = no click path from `/`. Mod in-links can't be concluded from a 254-page sample: the mod graph is sibling-to-sibling.)

Root cause for game×location: `gameRelatedLinks` linked every page to the *same first three locations*, so ~73% of combos had no inbound link at all. Fixed with a deterministic ring (next three locations, next two games at the same place, the real-datacenter locations, the game hub, and the new `/locations` hub). The general "X game server hosting" page per location now links all of its per-game 

## 6. Structured data

Types seen on the sampled pages: Organization + WebSite (site-wide), BreadcrumbList, FAQPage, Product/Offer, BlogPosting, Blog, ItemList, CollectionPage, HowTo, SoftwareApplication, WebApplication, TechArticle, GameServer. The audit's validator checks JSON parses and the properties Google's rich-result docs require (Organization name+url, Offer price+priceCurrency, FAQ Question/Answer, ListItem po
Note: the site-wide WebSite `SearchAction` points at `/domains?q=`; Google retired the sitelinks search box, so it earns nothing — harmless, left in place.

## 7. Images, page weight, speed
/**
 * Mod page quality bar (seo-014). A mod page is indexable only when it has the
 * substance of a page worth ranking; everything below the bar is `noindex,follow`
 * (still crawlable and linked, just not offered to the index) and is left out of the
 * sitemap. Evidence behind the bar: 64,853 mod pages vs 28 search-referred visits in
 * 30 days, 12,223 of 19,920 Minecraft mods with <80-char descriptions
 * (docs/SEO-AUDIT-2026-10.md §4), and Google's scaled-content policy.
 *
 * The bar (all must hold):
 *   1. real downloads from the source (>= Setting seo_mod_noindex_below_downloads, default 100;
 *      at least 1 when that floor is 0) — never our own install counts;
 *   2. words: a description (or the source's long body) of >= 300 characters, OR our own
 *      compatibility/impact note (impactNote);
 *   3. compatibility data: Minecraft needs loaders AND game versions (the loader x version
 *      matrix); every other game needs a declared server-side status (required/optional);
 *      a mod flagged client-only ("unsupported") never passes;
 *   4. dependencies known: the row was verified against its source (verifiedAt set), which is
 *      what populates dependencyCount;
 *   5. a working install CTA: the (game, source) pair is one the worker can really install
 *      (lib/mod-install-support.ts).
 *
 * This file has a pure TypeScript judge (used by the page) and the same rule as a SQL
 * fragment (used by the sitemap query). test/mod-quality.test.ts keeps them in step.
 * Setting `seo_mod_quality_bar` = off disables the bar entirely (default on).
 */
import { Prisma } from "@prisma/client";
import { FAMILY_SOURCES, INSTALLABLE_FAMILIES, RESOLVABLE_SOURCES, installSupport } from "./mod-install-support";

export const MOD_DESC_MIN_CHARS = 300;

export interface ModQualityInput {
  gameFamily: string;
  source: string;
  downloads: number | null;
  description: string | null;
  longDescription: string | null;
  impactNote: string | null;
  loaders: string[];
  gameVersions: string[];
  serverSide: string | null;
  verifiedAt: Date | null;
}

export type ModBarFailure = "downloads" | "words" | "compat" | "dependencies" | "install";

const len = (s: string | null | undefined) => (s ?? "").trim().length;

export function modBarFailures(m: ModQualityInput, minDownloads: number): ModBarFailure[] {
  const out: ModBarFailure[] = [];
  if ((m.downloads ?? 0) < Math.max(1, minDownloads)) out.push("downloads");
  if (len(m.longDescription) < MOD_DESC_MIN_CHARS && len(m.description) < MOD_DESC_MIN_CHARS && len(m.impactNote) === 0) out.push("words");
  const sideOk = m.serverSide === "required" || m.serverSide === "optional";
  const compat = m.gameFamily === "minecraft" ? m.loaders.length > 0 && m.gameVersions.length > 0 && m.serverSide !== "unsupported" : sideOk;
  if (!compat) out.push("compat");
  if (!m.verifiedAt) out.push("dependencies");
  if (!installSupport(m.gameFamily, m.source).ok) out.push("install");
  return out;
}

/** (family, source) pairs the worker can install — the SQL twin of installSupport(). */
export function installablePairs(): [string, string][] {
  const pairs: [string, string][] = [];
  for (const f of INSTALLABLE_FAMILIES) {
    const allowed = FAMILY_SOURCES[f];
    for (const s of allowed ?? RESOLVABLE_SOURCES) if (RESOLVABLE_SOURCES.has(s)) pairs.push([f, s]);
  }
  return pairs;
}

/** The bar as a SQL condition over "GameMod" (same rule as modBarFailures). */
export function modBarSql(minDownloads: number): Prisma.Sql {
  const pairs = installablePairs();
  return Prisma.sql`(
    coalesce("downloads", 0) >= ${Math.max(1, minDownloads)}
    AND (char_length(btrim(coalesce("longDescription", ''))) >= ${MOD_DESC_MIN_CHARS}
      OR char_length(btrim(coalesce("description", ''))) >= ${MOD_DESC_MIN_CHARS}
      OR char_length(btrim(coalesce("impactNote", ''))) > 0)
    AND (CASE WHEN "gameFamily" = 'minecraft'
        THEN cardinality("loaders") > 0 AND cardinality("gameVersions") > 0 AND "serverSide" IS DISTINCT FROM 'unsupported'
        ELSE "serverSide" IN ('required', 'optional') END)

