export async function countIndexableMods(minDownloads = 0): Promise<number> {
  try {
    const pol = await loadSeoPolicy();
    if (pol.modQualityBar) {
      // seo-014: only pages that clear the quality bar (lib/mod-quality.ts) are listed
      const r = await db.$queryRaw<{ n: number }[]>(Prisma.sql`SELECT count(*)::int AS n FROM "GameMod" WHERE "active" AND "upstreamOk" AND "duplicateOfId" IS NULL AND coalesce("downloads", 0) >= ${minDownloads} AND ${modBarSql(pol.modNoindexBelowDownloads)}`);
      return r[0]?.n ?? 0;
    }
    return await db.gameMod.count({ where: { active: true, upstreamOk: true, duplicateOfId: null, ...(minDownloads > 0 ? { downloads: { gte: minDownloads } } : {}) } });
  } catch {
    return 0;
  }
}

/** How many chunk sitemaps `countIndexableMods()`'s result needs, at `MOD_SITEMAP_CHUNK_SIZE` URLs each. */
export function modChunkCountFor(modCount: number): number {
  return modCount > 0 ? Math.ceil(modCount / MOD_SITEMAP_CHUNK_SIZE) : 0;
}

/**
 * One deterministic page of {family, slug} pairs. `orderBy: { id: "asc" }`
 * is load-bearing, not decorative: each /sitemap/[id].xml chunk is fetched
 * as its own independent request (possibly seconds or minutes apart, by a
 * crawler working through the index), so `skip`/`take` only partitions the
 * real table into complete, non-overlapping chunks if every request sees
 * the same stable ordering — an unordered `findMany` has no such guarantee.
 */
export async function listIndexableModSlugsChunk(
  chunkIndex: number,
  minDownloads = 0
): Promise<{ family: string; slug: string; lastModified: Date }[]> {
  const pol = await loadSeoPolicy();
  if (pol.modQualityBar) {
    // seo-014: same keyset paging, restricted to mods that clear the quality bar (lib/mod-quality.ts)
    const cond = Prisma.sql`"active" AND "upstreamOk" AND "duplicateOfId" IS NULL AND coalesce("downloads", 0) >= ${minDownloads} AND ${modBarSql(pol.modNoindexBelowDownloads)}`;
    let start: string | null = null;
    if (chunkIndex > 0) {
      const f = await db.$queryRaw<{ id: string }[]>(Prisma.sql`SELECT "id" FROM "GameMod" WHERE ${cond} ORDER BY "id" ASC OFFSET ${chunkIndex * MOD_SITEMAP_CHUNK_SIZE} LIMIT 1`);
      if (!f.length) return [];
      start = f[0].id;
    }
    const rows = await db.$queryRaw<{ gameFamily: string; slug: string; updatedAt: Date; upstreamUpdatedAt: Date | null }[]>(
      Prisma.sql`SELECT "gameFamily", "slug", "updatedAt", "upstreamUpdatedAt" FROM "GameMod" WHERE ${cond} ${start ? Prisma.sql`AND "id" >= ${start}` : Prisma.empty} ORDER BY "id" ASC LIMIT ${MOD_SITEMAP_CHUNK_SIZE}`,
    );
    return rows.map((r) => ({ family: r.gameFamily, slug: r.slug, lastModified: r.upstreamUpdatedAt && r.upstreamUpdatedAt > r.updatedAt ? r.upstreamUpdatedAt : r.updatedAt }));
  }
  const where = { active: true, upstreamOk: true, duplicateOfId: null, ...(minDownloads > 0 ? { downloads: { gte: minDownloads } } : {}) };
  // Keyset, not deep OFFSET: a plain skip/take on the wide GameMod rows made
  // Postgres sort and spill the whole prefix to disk for chunks 3+ (the 500s
  // seen on /sitemap/3..5.xml). Find the chunk's first id with an id-only
  // index scan, then read the chunk with `id >= start` (index range scan).
  let startId: string | undefined;
  if (chunkIndex > 0) {
    const first = await db.gameMod.findFirst({
      where,
      select: { id: true },
      orderBy: { id: "asc" },
      skip: chunkIndex * MOD_SITEMAP_CHUNK_SIZE,
    });
    if (!first) return [];
    startId = first.id;
  }
  const rows = await db.gameMod.findMany({
    where: startId ? { ...where, id: { gte: startId } } : where,
    select: { gameFamily: true, slug: true, updatedAt: true, upstreamUpdatedAt: true },
    orderBy: { id: "asc" },
    take: MOD_SITEMAP_CHUNK_SIZE,
  });
  return rows.map((r) => ({
    family: r.gameFamily,
    slug: r.slug,
    lastModified: r.upstreamUpdatedAt && r.upstreamUpdatedAt > r.updatedAt ? r.upstreamUpdatedAt : r.updatedAt,
  }));
}

