new='''/** Clamp for the cap setting: a chunk is MOD_SITEMAP_CHUNK_SIZE, and a sitemap file may never pass 50,000 URLs. */
export function effectiveSitemapCap(maxUrls: number): number {
  return maxUrls > 0 ? Math.min(Math.floor(maxUrls), 45_000) : 0;
}

/**
 * Quality-over-quantity gate for the SITEMAP only (pages outside it stay crawlable/indexable; noindex is a
 * separate policy). Base: active, upstream still exists, not a duplicate, real downloads >= the floor, and the
 * lib/mod-quality.ts bar when enabled. On top: a substantial description (longest of long/short description >=
 * seo_mod_sitemap_min_desc_chars). The survivors are ranked by downloads and capped at seo_mod_sitemap_max_urls.
 */
export function sitemapModCond(pol: { modQualityBar: boolean; modNoindexBelowDownloads: number; modSitemapMinDescChars: number }, minDownloads: number): Prisma.Sql {
  const parts: Prisma.Sql[] = [Prisma.sql`"active" AND "upstreamOk" AND "duplicateOfId" IS NULL AND coalesce("downloads", 0) >= ${minDownloads}`];
  if (pol.modQualityBar) parts.push(modBarSql(pol.modNoindexBelowDownloads));
  if (pol.modSitemapMinDescChars > 0) {
    parts.push(Prisma.sql`GREATEST(char_length(btrim(coalesce("longDescription", ''))), char_length(btrim(coalesce("description", '')))) >= ${pol.modSitemapMinDescChars}`);
  }
  return Prisma.join(parts, " AND ");
}

/** Number of mod URLs the sitemap will list (after the gate and the cap). */
export async function countIndexableMods(minDownloads = 0): Promise<number> {
  try {
    const pol = await loadSeoPolicy();
    const r = await db.$queryRaw<{ n: number }[]>(Prisma.sql`SELECT count(*)::int AS n FROM "GameMod" WHERE ${sitemapModCond(pol, minDownloads)}`);
    const n = r[0]?.n ?? 0;
    const cap = effectiveSitemapCap(pol.modSitemapMaxUrls);
    return cap > 0 ? Math.min(n, cap) : n;
  } catch {
    return 0;
  }
}

/** How many chunk sitemaps `countIndexableMods()`'s result needs, at `MOD_SITEMAP_CHUNK_SIZE` URLs each. */
export function modChunkCountFor(modCount: number): number {
  return modCount > 0 ? Math.ceil(modCount / MOD_SITEMAP_CHUNK_SIZE) : 0;
}

/**
 * One deterministic chunk of {family, slug}: the gated set ranked by downloads (ties by id, so the order is
 * stable between requests), cut at the cap, then paged with LIMIT/OFFSET (the ranked set is at most 45,000 rows,
 * so OFFSET is cheap; the old keyset trick was for 190K-row scans).
 */
export async function listIndexableModSlugsChunk(
  chunkIndex: number,
  minDownloads = 0,
): Promise<{ family: string; slug: string; lastModified: Date }[]> {
  const pol = await loadSeoPolicy();
  const cap = effectiveSitemapCap(pol.modSitemapMaxUrls);
  const offset = chunkIndex * MOD_SITEMAP_CHUNK_SIZE;
  const limit = cap > 0 ? Math.max(0, Math.min(MOD_SITEMAP_CHUNK_SIZE, cap - offset)) : MOD_SITEMAP_CHUNK_SIZE;
  if (limit <= 0) return [];
  const rows = await db.$queryRaw<{ gameFamily: string; slug: string; updatedAt: Date; upstreamUpdatedAt: Date | null }[]>(
    Prisma.sql`SELECT "gameFamily", "slug", "updatedAt", "upstreamUpdatedAt" FROM "GameMod" WHERE ${sitemapModCond(pol, minDownloads)} ORDER BY coalesce("downloads", 0) DESC, "id" ASC OFFSET ${offset} LIMIT ${limit}`,
  );
  return rows.map((r) => ({ family: r.gameFamily, slug: r.slug, lastModified: r.upstreamUpdatedAt && r.upstreamUpdatedAt > r.updatedAt ? r.upstreamUpdatedAt : r.updatedAt }));
}
