import { modNoindex } from "@/lib/seo-index-policy";
import "server-only";
import { notFound } from "next/navigation";
import { currentUser } from "@/lib/auth";
import { deployHref } from "@/lib/deploy-intent";
import { getEligibleServersForMod } from "@/lib/actions-mods";
import { renderModBody, type ModBodySource } from "@/lib/mod-markdown";
import {
  composedDescriptionFor,
  formatBytes,
  getCatalogMod,
  recommendedPlanFor,
  relatedCatalogMods,
  resolveDownloadUrl,
  type ModDetail,
} from "@/lib/mods-catalog";
import { esc, introSpan, usd, type NxmLoad } from "./lib";
import { withBanners } from "./mods-taxonomy";
import { liveBadges } from "@/lib/mod-verify/store";
import { badgeSentence } from "@/lib/mod-verify/status";
import { APP_URL } from "@/components/marketing/StructuredData";
import {
  ago, attr, browseHref, catOf, btnDeploy, btnGlass, dl, familyOr404, familyPlans, gameHref, iconOr, installable, loaderLabel,
  n, palette, portalModHref, regionsWithFlags, sourceLabel, tagTile, tierPrice, tierRam, xmodCard, type Family, type FamilyPlans,
} from "./mods-lib";

/**
 * /mods/[family]/[slug] — the Lithium design as the template for every mod.
 * Three layers (docs/HANDOFF.md):
 *   1. automatic, from the mod's real GameMod row (name, author, stats,
 *      loaders, versions, license, side support, gallery, related mods);
 *   2. tag-driven illustrations (mods-lib tagTile, a port of mod_tags.py;
 *      categories with no illustration get the neutral default);
 *   3. curated highlights — hand-written for Lithium only (the design's
 *      LITHIUM dict). Every other mod's highlights are built strictly from
 *      its real fields; nothing is invented.
 * Unknown / inactive / upstream-dead mod -> 404.
 */
type Curated = {
  summaryExtra?: string;
  details?: string[];
  highlights?: [string, string, "phys" | "ai" | "tick"][];
  vanilla?: string;
  sides?: { title: string; text: string; diagram: boolean };
  requires?: string;
  config?: string;
};
/** build_modpage.py LITHIUM — the design's curated layer, Lithium only. */
const CURATED: Record<string, Curated> = {
  "minecraft/lithium": {
    summaryExtra: "It speeds up the systems the game ticks without changing a single vanilla mechanic.",
    details: [
      "Lithium is a general-purpose optimization mod that improves a number of the game’s systems, including physics, mob AI and block ticking.",
      "Its goal is to leave vanilla behaviour completely unchanged, which has even led to it being allowed in official Minecraft speedrunning.",
      "It works on both the client and the server, and either side can run it without the other.",
      "A configuration system lets you disable any individual patch, which helps if another mod conflicts with one.",
    ],
    highlights: [
      ["Game physics", "Entity movement and collisions, handled with less work per tick.", "phys"],
      ["Mob AI", "Pathfinding and behaviour checks, optimized without changing how mobs act.", "ai"],
      ["Block ticking", "The world updates it runs constantly, done more efficiently.", "tick"],
    ],
    vanilla: "Lithium doesn’t change game mechanics, which is why it’s even allowed in official Minecraft speedrunning.",
    sides: { title: "Your players don’t need it", text: "It works on the server alone, so players join with a normal game. It also works on clients if they want it.", diagram: true },
    requires: "Fabric Loader on Fabric. Not even Fabric API is needed.",
    config: "Every patch can be switched off in its config file.",
  },
};

async function modOr404(p: Record<string, string>) {
  const f = await familyOr404(p.family);
  if (!p.slug) notFound();
  const mod = await getCatalogMod(f.family, p.slug);
  // public = active && upstreamOk (getCatalogMod already drops inactive rows)
  if (!mod || !mod.upstreamOk) notFound();
  return { f, mod };
}

/** Same meta description the live mod page builds (real longDescription/description, else real fields). */
function metaDescription(mod: ModDetail) {
  const raw = mod.longDescription?.trim() || mod.description?.trim() || "";
  if (raw) {
    const plain = raw.replace(/```[\s\S]*?```/g, " ").replace(/!\[[^\]]*\]\([^)]*\)/g, " ").replace(/\[([^\]]*)\]\([^)]*\)/g, "$1")
      .replace(/<[^>]+>/g, " ").replace(/\[\/?[a-z0-9]+[^\]]*\]/gi, " ").replace(/[#>*_`~]/g, " ").replace(/(^|\s)-+(?=\s)/g, " ").replace(/\s+/g, " ").trim();
    if (plain.length <= 160) return plain;
    const cut = plain.slice(0, 157), sp = cut.lastIndexOf(" ");
    return `${cut.slice(0, sp > 100 ? sp : 157)}…`;
  }
  return `${mod.name} for ${mod.gameFamilyLabel}, verified against ${sourceLabel(mod.source)} — real download counts, supported versions, and a direct download link.`;
}
const images = (mod: ModDetail) => [mod.iconUrl, ...mod.galleryUrls].filter((u): u is string => !!u);

export async function meta(p: Record<string, string>) {
  const { mod } = await modOr404(p);
  const img = mod.galleryUrls[0] ?? mod.iconUrl ?? undefined;
  return {
    title: `${mod.name} — ${mod.gameFamilyLabel} ${mod.category} | NxLabs`,
    description: metaDescription(mod),
    crumb: mod.name,
    ...(img ? { image: img } : {}),
    // no real demand signal, or below the page quality bar (lib/mod-quality.ts): keep it out of the index (lib/seo-index-policy.ts)
    ...((await modNoindex(mod.downloads, mod)) ? { noindex: true } : {}),
  };
}

const andList = (xs: string[]) => (xs.length < 2 ? xs.join("") : `${xs.slice(0, -1).join(", ")} and ${xs[xs.length - 1]}`);
const bodySource = (s: string): ModBodySource => (s === "modrinth" || s === "thunderstore" || s === "steam_workshop" ? s : "other");

export async function load(p: Record<string, string>): Promise<NxmLoad> {
  const { f, mod } = await modOr404(p);
  const cur = CURATED[`${mod.gameFamily}/${mod.slug}`];
  const T = mod.name;
  const src = sourceLabel(mod.source);
  const [related, download, plans, regions, user, nxv] = await Promise.all([
    relatedCatalogMods(mod, 8).then(withBanners),
    resolveDownloadUrl(mod),
    familyPlans(f.family),
    regionsWithFlags(),
    currentUser(),
    liveBadges([mod.id]).then((m) => m.get(mod.id) ?? null).catch(() => null),
  ]);
  const eligible = user ? await getEligibleServersForMod(mod.id) : { loggedIn: false, servers: [] };
  const support = installable(mod.gameFamily, mod.source);
  const { c1, c2 } = palette(mod);
  const summary = mod.description || composedDescriptionFor(mod);
  const up = ago(mod.upstreamUpdatedAt);
  const loaders = mod.loaders.map(loaderLabel);
  const latest = mod.gameVersions[mod.gameVersions.length - 1];
  const size = formatBytes(mod.fileBytes);
  const recommended = recommendedPlanFor(mod, plans.tiers.map((t) => ({ id: t.id, name: t.name, ramMB: t.ram * 1024, priceCents: Math.round((t.i ?? t.p) * 100), active: true })));
  const pick = plans.tiers.find((t) => t.id === recommended?.id) ?? plans.cheapest;

  // ── hero ──
  // "Nxeon Verified" ONLY from a live ModVerification (lib/mod-verify): an install
  // smoke test passed for a specific build + game version, unexpired. The older

  // smoke test passed for a specific build + game version, unexpired. The older
  // GameMod.verifiedAt only means "listing re-checked against its source", so it
  // is labelled that way and can't be mistaken for the badge.
  const nxvBadge = nxv ? `<a class="bv" href="/mods/verified" title="${esc(badgeSentence(f.label ?? mod.gameFamilyLabel, nxv))}">✓ Nxeon Verified</a>` : "";
  const badges = [nxvBadge, !nxv && mod.verified && '<span class="bc" title="Listing details re-checked against the source">Source-checked</span>', mod.featured && '<span class="bf">★ Featured</span>', `<span class="bc">${esc(catOf(mod).label)}</span>`].filt
  const stats = [
    dl(mod.downloads) && [dl(mod.downloads)!, "Downloads"],
    up && [up, "Last updated"],
    mod.license && [mod.license, "License"],
    loaders.length && [loaders.slice(0, 2).join(" · ") + (loaders.length > 2 ? ` +${loaders.length - 2}` : ""), "Loaders"],
    size && [size, "File size"],
    latest && [latest, "Latest game version"],
    [src, "Source"],
  ].filter(Boolean).slice(0, 4) as [string, string][];
  const actions = [
    `<a class="nxm-btn" href="#add"><span class="nxm-bt">Add to my server</span><span class="nxm-arw" aria-hidden="true">→</span></a>`,
    mod.url && btnGlass(mod.url, `Download from ${src}`, true),
  ].filter(Boolean).join("");

  // ── gallery (the mod's own source screenshots; hidden when it has none) ──
  const gallery = mod.galleryUrls.length ? galleryHtml(mod, src) : "";

  // ── about: the source's own long body, else the curated (Lithium) notes ──
  // presentational <span>/<svg> wrappers (Vintage Story ModDB bodies are HTML) carry no
  // text of their own; drop them so the escape-first renderer doesn't print them
  const body = mod.longDescription
    ? renderModBody(mod.longDescription.replace(/<svg[\s\S]*?<\/svg>/gi, "").replace(/<\/?span\b[^>]*>/gi, ""), bodySource(mod.source), 6000)
    : null;
  const details = body
    ? `<div class="dtl" id="dtl"><div class="nxm-modbody">${body.html}</div>${body.truncated && mod.url ? `<p><a href="${attr(mod.url)}" target="_blank" rel="noopener noreferrer nofollow ugc">Read the full description on ${esc(src)} →</a></p>` : ""}</div><bu
    : cur?.details
      ? `<div class="dtl" id="dtl"><ul>${cur.details.map((x) => `<li>${esc(x)}</li>`).join("")}</ul></div><button type="button" class="dtl-t" id="dtl-t" aria-expanded="false">Read the full description</button>`
      : "";
  const aboutLabel = body ? `From ${src}` : cur?.details ? "Curated by NxLabs" : `From ${src}`;

  // ── highlights: curated for Lithium; real fields for every other mod ──
  const hl = highlightsHtml(mod, f, cur, { loaders, latest, size, up });

  // ── side support (Modrinth-style server_side flag) ──
  const sides = sidesFor(mod, src, cur);
  const sidesHtml = sides
    ? `<div class="blk"><div class="blk-h"><h3>${esc(sides.title)}</h3><span class="lay ${cur?.sides ? "cur" : "auto"}">${cur?.sides ? "Curated by NxLabs" : "From source side support"}</span></div><p class="blk-p">${esc(sides.text)}</p>${sides.diagram ? diagra
    : "";

  // ── compatibility + verified-at-source cards ──
  const runsOn = mod.serverSide === "required" ? '<span class="tg ok">Server</span><small>required on the server</small>'
    : mod.serverSide === "optional" ? (cur?.sides?.diagram ? '<span class="tg ok">Server</span><span class="tg ok">Client</span><small>either side alone</small>' : '<span class="tg ok">Server</span><small>optional on the server</small>')
    : mod.serverSide === "unsupported" ? '<span class="tg">Client only</span>' : "";
  const requires = [cur?.requires ?? (mod.appliesToVariant && `One-click install needs a ${loaderLabel(mod.appliesToVariant)} server.`),
    mod.dependencyCount > 0 && `${n(mod.dependencyCount)} other ${mod.dependencyCount === 1 ? "project" : "projects"} installed alongside it.`].filter(Boolean).join(" ");
  const row = (dt: string, dd: string) => `<div><dt>${dt}</dt><dd>${dd}</dd></div>`;
  const compat = [
    row("Game", esc(mod.gameFamilyLabel)),
    loaders.length && row("Loaders", loaders.map((l) => `<span class="tg">${esc(l)}</span>`).join("")),
    runsOn && row("Runs on", runsOn),
    latest && row("Game versions", `${esc(latest)}${mod.gameVersions.length > 1 ? ` <small>and ${n(mod.gameVersions.length - 1)} earlier</small>` : ""}`),
    requires && row("Requires", esc(requires)),
    size && row("File size", esc(size)),
    cur?.config && row("Configurable", esc(cur.config)),
  ].filter(Boolean).join("");
  const vfy = [
    `<li><span class="vk">✓</span><span><b>${esc(src)}</b><small>${mod.verifiedAt ? `Official listing, checked ${mod.verifiedAt.toISOString().slice(0, 10)}` : "Official listing"}</small></span>${mod.url ? `<a href="${attr(mod.url)}" target="_blank" rel="noop
    mod.authorName && `<li><span class="vk">✓</span><span><b>Author</b><small>${esc(mod.authorName)}, as published on ${esc(src)}</small></span></li>`,
    `<li><span class="vk">✓</span><span><b>License</b><small>${esc(mod.license ?? "Not published by the source")}</small></span><em>${mod.paid ? "Paid" : "Free"}</em></li>`,
  ].filter(Boolean).join("");

  // ── add to a server: the real flow (portal installMod) or a real deploy ──
  const add = addPanel(mod, f, plans, pick?.id ?? null, regions, eligible, support);

  // ── FAQ, generated from the mod's own source data ──
  const faq = [
    sides && [`Do my players need to install ${T}?`, sides.text],
    loaders.length && [`Which loaders does it support?`, `${andList(loaders)}.${cur?.requires ? ` ${cur.requires}` : ""}`],
    [`Is it free?`, mod.paid ? `No. ${T} is a paid listing on ${src}.` : `Yes. ${T} is free to download from ${src}.${mod.license ? ` Its license is ${mod.license}.` : ""}`],
    [`How do I add it to my Nxeon server?`, support.ok
      ? `Use “Add to a server” on this page, or open NxLabs from your dashboard. We install it, restart your server and switch it on.`
      : plans.tiers.length
        ? `${support.message.replace(/ — /g, ": ")} Download ${T} from ${src} and upload it to your Nxeon ${mod.gameFamilyLabel} server in Files.`
        : `NxLabs doesn’t install ${mod.gameFamilyLabel} mods for you. Download ${T} free from ${src}.`],
  ].filter(Boolean) as [string, string][];

  // ── final CTA ──
  const final = pick
    ? `<p>Deploy in about a minute from ${tierPrice(plans.cheapest!)} a month, then ${support.ok ? `add ${esc(T)} in one click` : `upload ${esc(T)} in Files`}.</p><div class="final-ctas">${btnDeploy(deployHref({ service: "game", gameFamily: f.family, gamePlanI
    : `<p>Free to download from ${esc(src)}.</p><div class="final-ctas">${mod.url ? btnDeploy(mod.url, `Download from ${src}`).replace("nxm-btn au-hov", "nxm-btn") : ""}${btnGlass(gameHref(f.family), `More ${mod.gameFamilyLabel} mods`)}</div>`;

  const deployMap: Record<string, string> = {};
  for (const t of plans.tiers) for (const r of regions.length ? regions : [{ code: "" }]) {
    deployMap[`${t.id}|${r.code}`] = deployHref({ service: "game", gameFamily: f.family, gamePlanId: t.id, region: r.code || undefined });
  }

  return {
    slots: {
      "art.c1": c1, "art.c2": c2,
      // the mod's own lead screenshot as the hero art when its source has one; else the design's
      // category-coloured graph art
      "hero.art:html": mod.galleryUrls[0]
        ? `<img src="${attr(mod.galleryUrls[0])}" alt="" decoding="async" fetchpriority="high" referrerpolicy="no-referrer" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;filter:saturate(1.05)" onerror="this.remove()">`
        : "",
      "game.name": mod.gameFamilyLabel,
      "game.href": gameHref(f.family),
      "browse.href": browseHref(f.family, { sort: "downloads" }),
      "mod.name": T,
      "mod.ic:html": mod.iconUrl ? iconOr(mod, 2) : `<i>${esc(T.slice(0, 2))}</i>`,
      "mod.dmic:html": iconOr(mod, 2),
      "badges:html": badges,
      "by:html": mod.authorName ? `by <b>${esc(mod.authorName)}</b> · for ${esc(mod.gameFamilyLabel)}` : `for ${esc(mod.gameFamilyLabel)}`,
      "summary": summary + (cur?.summaryExtra ? ` ${cur.summaryExtra}` : ""),
      "summaryShort": summary,
