}

function galleryHtml(mod: ModDetail, src: string) {
  const g = mod.galleryUrls;
  const thumbs = g.map((u, i) => `<button type="button" class="gth${i === 0 ? " on" : ""}" data-i="${i}" aria-label="Screenshot ${i + 1}"><img src="${attr(u)}" alt="" loading="lazy" referrerpolicy="no-referrer" width="320" height="180"></button>`).join("");
  return `<section class="section gal" id="gallery" aria-labelledby="gl-title" style="padding-top:10px"><div class="container">
  <div class="gp-head"><div><h2 class="h2" id="gl-title">Gallery</h2></div><span class="gal-src">From ${esc(src)}</span></div>
  <div class="gal-grid"><button type="button" class="gal-main" id="gal-main" aria-label="Open screenshot"><img id="gal-img" src="${attr(g[0])}" alt="${attr(mod.name)} screenshot 1" referrerpolicy="no-referrer" width="1280" height="720"><span class="gal-zoom">�
</div></section>
<div class="lbx" id="lbx" hidden role="dialog" aria-modal="true" aria-label="Screenshot viewer"><button type="button" class="lbx-x" aria-label="Close">×</button><button type="button" class="lbx-p" aria-label="Previous">‹</button><img id="lbx-img" alt="" ref
}

const ILLS: Record<string, string> = {
  phys: '<div class="wd-ill wd-phys" aria-hidden="true"><i></i><i></i><i></i></div>',
  ai: '<div class="wd-ill wd-ai" aria-hidden="true"><i></i><i></i><i></i><i></i></div>',
  tick: `<div class="wd-ill wd-tick" aria-hidden="true">${"<i></i>".repeat(16)}</div>`,
};

function highlightsHtml(mod: ModDetail, f: Family, cur: Curated | undefined, x: { loaders: string[]; latest?: string; size: string | null; up: string | null }) {
  let items: [string, string, string][];
  let label: string, cls: string;
  if (cur?.highlights) {
    items = cur.highlights; label = "Curated by NxLabs"; cls = "cur";
  } else {
    const v = mod.gameVersions.length;
    const cand: ([string, string] | null)[] = [
      x.latest ? ["Game versions", v > 1 ? `Supports ${n(v)} ${f.label} versions, the newest being ${x.latest}.` : `Built for ${f.label} ${x.latest}.`] : null,
      x.loaders.length ? ["Loaders", `Runs on ${andList(x.loaders)}.`] : null,
      x.size || mod.verifiedAt ? ["Footprint", `${x.size ? `A ${x.size} download, ` : ""}rated a ${mod.impact} load on a server.${mod.impactNote ? ` ${mod.impactNote}` : ""}`.replace(/^rated/, "Rated")] : null,
      mod.dependencyCount > 0 ? ["Dependencies", `Needs ${n(mod.dependencyCount)} other ${mod.dependencyCount === 1 ? "project" : "projects"} installed alongside it.`] : null,
      mod.license ? ["License", `Published under ${mod.license}.`] : null,
      x.up ? ["Last update", `Its author last shipped an update ${x.up}.`] : null,
    ];
    const kinds = ["tick", "ai", "phys"];
    items = cand.filter((c): c is [string, string] => !!c).slice(0, 3).map((c, i) => [c[0], c[1], kinds[i]]);
    label = "From source data"; cls = "auto";
    if (items.length < 2) return "";
  }
  return `<div class="blk"><div class="blk-h"><h3>Highlights</h3><span class="lay ${cls}">${label}</span></div><div class="wd3">${items.map(([t, d, k]) => `<article class="wd">${ILLS[k]}<h3>${esc(t)}</h3><p>${esc(d)}</p></article>`).join("")}</div></div>`;
}

/** mod_tags.py sides(), from the one side flag the catalogue carries (server_side). */
function sidesFor(mod: ModDetail, src: string, cur?: Curated): { title: string; text: string; diagram: boolean } | null {
  if (cur?.sides) return cur.sides;
  if (mod.serverSide === "required") return { title: "Runs on your server", text: `${src} lists ${mod.name} as required on the server. Check its ${src} page to see whether players need it too.`, diagram: false };
  if (mod.serverSide === "optional") return { title: "Works on a server", text: `${src} lists server-side support for ${mod.name} as optional: it can run on a server, but isn’t required there.`, diagram: false };
  if (mod.serverSide === "unsupported") return { title: "Client-side mod", text: `${src} lists ${mod.name} as not supported on servers. It runs in players’ own games, not on your server.`, diagram: false };
  return null;
}

function diagram(mod: ModDetail) {
  const T = mod.name;
  return `<div class="sdg" aria-hidden="true"><div class="sdg-srv"><span class="dm-l" style="--c1:#3FD89A;--c2:#3EDCF2">${esc(T.slice(0, 2))}</span><b>Your server</b><small>${esc(T)} installed</small></div><svg class="sdg-l" viewBox="0 0 300 240" preserveAspec
}

function addPanel(mod: ModDetail, f: Family, plans: FamilyPlans, pickId: string | null,
  regions: { code: string; label: string; flag: string }[], eligible: { loggedIn: boolean; servers: { id: string; hostname: string; label: string | null; status: string }[] },
  support: { ok: true } | { ok: false; message: string }) {
