 */

export interface VersionFact {
  versionNumber: string;
  channel: string;
  gameVersions: string[];
  loaders: string[];
  publishedAt: Date | null;
  depList: unknown;
}

export interface DepFact {
  kind: "required" | "optional" | "incompatible" | "embedded";
  name: string;
