const KINDS = new Set(["required", "optional", "incompatible", "embedded"]);

/** Numeric-aware compare for game versions like 1.8.9 < 1.20.1; non-numeric parts compare as text. */
export function compareGameVersions(a: string, b: string): number {
  const pa = a.split(/[.\-]/), pb = b.split(/[.\-]/);
  for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
    const x = pa[i] ?? "", y = pb[i] ?? "";
    const nx = /^\d+$/.test(x), ny = /^\d+$/.test(y);
    if (nx && ny) { if (+x !== +y) return +x - +y; }
    else if (x !== y) return x < y ? -1 : 1;
  }
  return 0;
}

/** "1.8.8 to 1.21.4 (31 versions)" / "1.20.1" / "" — the real range, never an invented one. */
export function versionRange(vs: string[]): string {
  const u = [...new Set(vs)].sort(compareGameVersions);
  if (!u.length) return "";
  if (u.length === 1) return u[0];
  return `${u[0]} to ${u[u.length - 1]} (${u.length} versions)`;
}

export interface LoaderRow { loader: string; range: string; newest: string }

/** Per loader, the game versions any recorded build supports (union across the given builds). */
export function loaderMatrix(builds: Pick<VersionFact, "gameVersions" | "loaders">[]): LoaderRow[] {
  const by = new Map<string, Set<string>>();
  for (const b of builds) for (const l of b.loaders) {
    const s = by.get(l) ?? new Set<string>();
    for (const g of b.gameVersions) s.add(g);
    by.set(l, s);
  }
  return [...by.entries()]
    .map(([loader, s]) => { const vs = [...s].sort(compareGameVersions); return { loader, range: versionRange(vs), newest: vs[vs.length - 1] ?? "", n: vs.length }; })
    .sort((a, b) => b.n - a.n || a.loader.localeCompare(b.loader))
    .map(({ loader, range, newest }) => ({ loader, range, newest }));
}

/** Newest build's declared dependencies (normalised ModVersion.depList), deduplicated by project. */
export function parseDeps(depList: unknown): { kind: DepFact["kind"]; source: string; projectId: string; name: string | null }[] {
  if (!Array.isArray(depList)) return [];
  const seen = new Set<string>();
  const out: { kind: DepFact["kind"]; source: string; projectId: string; name: string | null }[] = [];
  for (const d of depList) {
    if (!d || typeof d !== "object") continue;
    const o = d as Record<string, unknown>;
    if (typeof o.projectId !== "string" || typeof o.source !== "string" || !KINDS.has(String(o.kind))) continue;
    const k = `${o.kind}:${o.source}:${o.projectId}`;
    if (seen.has(k)) continue;
    seen.add(k);
    out.push({ kind: o.kind as DepFact["kind"], source: o.source, projectId: o.projectId, name: typeof o.name === "string" && o.name ? o.name : null });
  }
  return out;
}

