import test from "node:test";
import assert from "node:assert/strict";
import { compareGameVersions, versionRange, loaderMatrix, parseDeps, newestDeps, dedupeLeadingName, onNxeonHtml, type OnNxeonInput } from "../lib/mod-onxeon";
import { effectiveSitemapCap } from "../lib/sitemap-mods";

test("game versions sort numerically, not lexically", () => {
  assert.ok(compareGameVersions("1.8.9", "1.20.1") < 0);
  assert.equal(versionRange(["1.21.4", "1.8.8", "1.20.1", "1.8.8"]), "1.8.8 to 1.21.4 (3 versions)");
  assert.equal(versionRange(["1.20.1"]), "1.20.1");
  assert.equal(versionRange([]), "");
});

test("loader matrix is the union of recorded builds per loader, widest first", () => {
  const m = loaderMatrix([
    { gameVersions: ["1.20.1", "1.20.4"], loaders: ["fabric", "forge"] },
    { gameVersions: ["1.21"], loaders: ["fabric"] },
  ]);
