/**
 * Page numbers to render as real <a href> links in a pager, chosen so a crawler (or a person) can reach ANY page
 * of a very long listing in a handful of hops instead of walking prev/next thousands of times: first, last, the
 * neighbours, and logarithmic jumps (current +/- 10, 100, 1,000 ...). From page 1 of 7,131 pages, any page is at
 * most about 4 x 9 hops away; the old pager only linked 1, current +/- 2 and the last page.
 */
export function pagerPages(current: number, total: number): number[] {
  const set = new Set<number>([1, total, current - 2, current - 1, current, current + 1, current + 2]);
  for (let step = 10; step < total; step *= 10) {
    for (const m of [1, 2, 3, 4, 5, 6, 7, 8, 9]) {
      const d = step * m;
      if (d >= total) break;
      set.add(current + d); set.add(current - d);
    }
  }
  return [...set].filter((x) => Number.isInteger(x) && x >= 1 && x <= total).sort((a, b) => a - b);
}
