import { pagerPages } from "../lib/seo-pager";
import { anonModCacheControl, ANON_PAGE_CACHE_CONTROL } from "../lib/seo-cache";

test("pager links reach any page of a 7,131-page listing in few hops", () => {
  const total = 7131;
  const reach = (from: number) => pagerPages(from, total);
  // BFS hops from page 1 to a far page
  const dist = new Map<number, number>([[1, 0]]);
  let frontier = [1];
  while (frontier.length && !dist.has(5000)) {
    const next: number[] = [];
    for (const p of frontier) for (const q of reach(p)) if (!dist.has(q)) { dist.set(q, dist.get(p)! + 1); next.push(q); }
    frontier = next;
  }
  assert.ok((dist.get(5000) ?? 99) <= 6);
  assert.ok(reach(3000).length < 60, "link count stays bounded");
  assert.ok(reach(1).includes(7131) && reach(1).includes(2));
  assert.deepEqual(pagerPages(1, 1), [1]);
});

test("anonymous mod pages get a shareable cache header; personalised requests never do", () => {
  const ok = { method: "GET", pathname: "/mods/minecraft/essentialsx", search: "", cookie: null, authorization: null };
  assert.equal(anonModCacheControl(ok), ANON_PAGE_CACHE_CONTROL);
  assert.equal(anonModCacheControl({ ...ok, cookie: "_ga=1; theme=dark" }), ANON_PAGE_CACHE_CONTROL);
  assert.equal(anonModCacheControl({ ...ok, cookie: "a=b; nxeon_session=abc" }), null);
  assert.equal(anonModCacheControl({ ...ok, cookie: "nxeon_session_imp=abc" }), null);
  assert.equal(anonModCacheControl({ ...ok, authorization: "Bearer x" }), null);
  assert.equal(anonModCacheControl({ ...ok, method: "POST" }), null);
  assert.equal(anonModCacheControl({ ...ok, search: "?q=lith" }), null);
  assert.equal(anonModCacheControl({ ...ok, search: "?page=3" }), ANON_PAGE_CACHE_CONTROL);
  assert.equal(anonModCacheControl({ ...ok, pathname: "/dashboard" }), null);
  assert.equal(anonModCacheControl({ ...ok, pathname: "/mods/verified" }), null);
  assert.equal(anonModCacheControl({ ...ok, pathname: "/mods/games/minecraft/all" }), ANON_PAGE_CACHE_CONTROL);
});
